import{z as n,x as i,o as e,c as p,q as r,j as o,D as a,d as s,s as A,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"掩模粗糙度","description":"","frontmatter":{"title":"掩模粗糙度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-roughness.md","filePath":"litho/mask-roughness.md","lastUpdated":1791413859000}'),d={name:"litho/mask-roughness.md"};function D(h,E,m,u,F,c){const l=i("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="掩模粗糙度" tabindex="-1">掩模粗糙度 <a class="header-anchor" href="#掩模粗糙度" aria-label="Permalink to &quot;掩模粗糙度&quot;">​</a></h1><div class="epigraph"><p>胶的 LER 不全是光子和酸。掩模吸收体边沿的粗糙经光学传递，成为硅片上抹不掉的低频底噪。</p><footer>—— 据 Naulleau 对 mask roughness 与 LER；Mack 边缘粗糙框架</footer></div><p><a href="/litho/mask-3d-best-focus-shift">上一课</a>把三维电磁写成平均焦移。缺口是边沿的随机：掩模粗糙度（mask roughness / mask LER）。修复能否在不毁掉多层的前提下改这块边，留给<a href="/litho/euv-mask-repair">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BF 偏移是确定的、图形相关的。掩模粗糙是随机的、沿边沿的高度与位置涨落。EUV 的光学传递函数对掩模高频仍有一定响应，尤其低 \\(k_1\\) 时掩模误差增强因子（MEEF）大，掩模上 1 nm 的边沿噪声可以在硅片上放大。Naulleau 把 EUV LER 预算拆成：光子散粒、胶化学、以及掩模贡献——后一项不随剂量消失。加剂量压随机，掩模底噪会露出来。</p><p>缺口是把掩模 LER 从胶随机里分开，而不是再讲一次 RLS 三角。空白多层的相位粗糙（表面高度）与吸收体线边粗糙是两桶：前者更像散斑/对比噪声，后者更像边沿位置噪声。</p><p><span class="marginnote">MEEF（掩模误差增强因子）回答的是&quot;掩模上的错到了硅片被放大几倍&quot;：MEEF 为 4 意味着掩模边沿挪 1 nm，硅片边沿跟着挪 4 nm。低 \\(k_1\\) 成像时 MEEF 常到 2-4 以上，这正是掩模上几纳米的粗糙能变成硅片底噪的放大器。</span></p><p><span class="marginnote">DUV 掩模粗糙相对 \\(k_1\\) 往往可忽略。EUV 短波 + 高 MEEF 把它抬成一等项。不要用「掩模厂 CD 合格」代替粗糙频谱合格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：掩模 SEM 或 AFM 得边沿 PSD；光化显微镜看打印后的传递。规格按频段：低频进 CDU/套刻，中高频进 LER/LWR。写入：电子束邻近、抗蚀剂和干法侧壁共同决定吸收体 PSD；多层沉积决定相位粗糙。OPC 不能「画平」随机边沿，只能避免把高 MEEF 图形放在粗糙最敏感的节距上。</p><p>与照明：极子改变传递函数，某些频率被放大。SMO 若只优化平均 NILS，可能选中对掩模粗糙更敏感的瞳——预算要联立。</p><h3 id="空白相位粗糙与线边要分桶" tabindex="-1">空白相位粗糙与线边要分桶 <a class="header-anchor" href="#空白相位粗糙与线边要分桶" aria-label="Permalink to &quot;空白相位粗糙与线边要分桶&quot;">​</a></h3><p>多层表面高度的随机相位在亮场像散斑，吸收体 LER 在边沿像位置噪声。修空白用再抛或筛选坯；修线边用写入与干法。混成一个「掩模粗糙 nm」会拧错旋钮。光化显微镜比 DUV SEM 更接近打印，相位项尤其如此。</p>',13)),(e(),o(B,null,{default:a(()=>[A(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E8%BE%B9%E6%B2%BF%20PSD%22%5D%20--%3E%20MEEF%5B%22%E5%85%89%E5%AD%A6%E4%BC%A0%E9%80%92%20%2F%20MEEF%22%5D%0A%20%20ML%5B%22%E5%A4%9A%E5%B1%82%E7%9B%B8%E4%BD%8D%E7%B2%97%E7%B3%99%22%5D%20--%3E%20SPEC%5B%22%E5%AF%B9%E6%AF%94%20%2F%20%E6%95%A3%E6%96%91%E7%B1%BB%E5%99%AA%E5%A3%B0%22%5D%0A%20%20MEEF%20--%3E%20WAFER%5B%22%E7%A1%85%E7%89%87%20LER%20%E5%BA%95%E5%99%AA%22%5D%0A%20%20DOSE%5B%22%E5%8A%A0%E5%89%82%E9%87%8F%22%5D%20--%3E%20PH%5B%22%E5%85%89%E5%AD%90%E9%A1%B9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20PH%20--%3E%20WAFER%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"成像是掩模频谱乘 TCC。边沿位置的随机相位/振幅调制出现在硅片边沿的随机位移。短波长让同样的物理粗糙对应更高的光学频率；部分相干又决定哪些频率进像。相位粗糙相当于随机的弱相位物，贡献类似散斑，在亮场更明显。修复若用沉积补边，可能引入新的局部粗糙峰——下一课的代价。",-1)),(e(),o(B,null,{default:a(()=>[A(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PSD%5B%22%E8%BE%B9%E6%B2%BF%E6%B6%A8%E8%90%BD%E6%8C%89%E7%A9%BA%E9%97%B4%E9%A2%91%E7%8E%87%E5%88%86%E6%A1%B6%22%5D%20--%3E%20LF%5B%22%E4%BD%8E%E9%A2%91%3A%20%E6%85%A2%E5%8F%98%E5%8C%96%22%5D%0A%20%20PSD%20--%3E%20HF%5B%22%E4%B8%AD%E9%AB%98%E9%A2%91%3A%20%E5%BF%AB%E5%8F%98%E5%8C%96%22%5D%0A%20%20LF%20--%3E%20CDU%5B%22%E8%BF%9B%20CDU%20%2F%20%E5%A5%97%E5%88%BB%E9%A2%84%E7%AE%97%22%5D%0A%20%20HF%20--%3E%20LER%5B%22%E8%BF%9B%20LER%20%2F%20LWR%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20DOSE%5B%22%E6%8F%90%E9%AB%98%E6%9B%9D%E5%85%89%E5%89%82%E9%87%8F%22%5D%20--%3E%20PH%5B%22%E5%85%89%E5%AD%90%E9%9A%8F%E6%9C%BA%E9%A1%B9%E6%8C%89%E6%A0%B9%E5%8F%B7N%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DOSE%20--%3E%20FLAT%5B%22%E6%8E%A9%E6%A8%A1%E9%A1%B9%E4%B8%80%E7%82%B9%E4%B8%8D%E5%8F%98%E5%B0%8F%22%5D%0A%20%20PH%20--%3E%20LER%0A%20%20FLAT%20--%3E%20LER%0A%20%20LER%20--%3E%20FLOOR%5B%22%E5%89%82%E9%87%8F%E5%8A%A0%E5%A4%9F%E5%90%8E%E6%8E%A9%E6%A8%A1%E6%88%90%E4%B8%BA%E5%9C%B0%E6%9D%BF%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">光子散粒噪声随剂量按根号下降：剂量翻 4 倍，随机涨落只降一半，而掩模粗糙贡献一动不动。所以预算要先把&quot;加剂量能压的项&quot;除干净，剩下压不掉的那部分，才是掩模真正要背的账。</span></p><p><span class="marginnote">可以把空白多层相位粗糙想象成毛玻璃：它不打歪边沿，而是让整片亮度起雾一样的涨落；吸收体 LER 则像剪纸剪歪的刀路，直接把边剪毛。两者修法不同——前者抛坯或筛选，后者抓写入与干法刻蚀，混为一谈就会拧错旋钮。</span></p><p><span class="marginnote">Naulleau 的公开论述强调：EUV LER 不能单靠胶和剂量解释。掩模贡献要用光化验证，而不是只信 DUV 掩模 SEM。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写电子束或气助修复的工艺窗口，下一课才写 EUV 特有的修复约束。不重写掩模厂 e-beam 写入课。加剂量压胶随机之后，掩模 PSD 会成为 LER 地板，要尽早用光化确认。出处：Naulleau mask roughness；Mack LER；MEEF 通识。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模边沿与多层相位粗糙构成不随剂量消失的 LER 底噪。</li><li>高 MEEF 和 EUV 传递把掩模 PSD 放大到硅片。</li><li>下一课：修缺陷时如何避免把粗糙和相位坑修得更糟。</li><li>出处：Naulleau；Mack。</li></ul>',7))])}const k=n(d,[["render",D]]);export{_ as __pageData,k as default};
